def _count_sentences_impl(text: str) -> int:
    import re

    return len([part for part in re.split(r"[.!?]+", text) if part.strip()])


def count_sentences(text: str) -> int:
    """Count the sentences in a piece of text (split on '.', '!' and '?')."""
    return _count_sentences_impl(text)
